import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        long n = Long.parseLong(s);

        long low = 0, high = 60; // since n <= 1e18, k won't exceed 60
        while (low < high) {
            long mid = (low + high + 1) / 2;
            if (can(mid, n)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        System.out.println(low);
    }

    // Check if (k+1)*2^k <= n without overflow
    private static boolean can(long k, long n) {
        // compute 2^k, but stop if exceeds n
        if (k >= 60) return false; // 2^60 > 1e18
        long pow2 = 1L << k; // safe for k < 63
        // Now check (k+1)*pow2 <= n without overflow
        if (pow2 > n / (k + 1)) return false;
        long val = (k + 1) * pow2;
        return val <= n;
    }
}

