public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        long n = Long.parseLong(s);

        long lo = 0, hi = 60; // enough since n <= 1e18
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            if (can(mid, n)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        System.out.println(lo);
    }

    private static boolean can(long k, long n) {
        // check if 2^k <= n * (k + 1)
        // compute 2^k with overflow check
        long pow = 1;
        for (int i = 0; i < k; i++) {
            if (pow > Long.MAX_VALUE / 2) return false;
            pow <<= 1;
        }

        // check n * (k + 1) without overflow
        if (n > Long.MAX_VALUE / (k + 1)) return true; // RHS is effectively infinite
        long rhs = n * (k + 1);
        return pow <= rhs;
    }
}

