public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        long n = Long.parseLong(s);

        long low = 0, high = 60; // enough since n <= 1e18
        while (low < high) {
            long mid = (low + high + 1) / 2;
            if (can(mid, n)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        System.out.println(low);
    }

    // Check if 2^k <= n * (k + 1) without overflow
    private static boolean can(long k, long n) {
        long lhs = 1; // 2^k
        for (int i = 0; i < k; i++) {
            if (lhs > Long.MAX_VALUE / 2) return false; // overflow guard
            lhs <<= 1;
        }

        long rhs;
        if (n > Long.MAX_VALUE / (k + 1)) {
            rhs = Long.MAX_VALUE;
        } else {
            rhs = n * (k + 1);
        }

        return lhs <= rhs;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        long n = Long.parseLong(s);

        // We need the largest k such that F_{k+2} - 1 <= n,
        // where F is Fibonacci with F1 = 1, F2 = 1.
        long prev = 1; // F1
        long curr = 1; // F2
        long fibKPlus2 = 2; // F3
        int k = 1; // corresponds to F_{k+2} = F3

        while (fibKPlus2 - 1 <= n) {
            long next = prev + curr;
            prev = curr;
            curr = next;
            fibKPlus2 = curr; // as we move forward, curr is F_{k+3}, etc.
            k++;
        }

        // The loop exits when F_{k+2} - 1 > n, so answer is k-1
        System.out.println(k - 1);
    }
}
